#!/usr/bin/env python3
"""
install_stage6.py - puts the three Stage 6 files in their repo places, no matter what the downloaded files are called.

HOW (one step, from the cf-worker folder):
    cd /workspaces/boltane-workers-poc/files12/cf-worker
    python install_stage6.py

It refuses to run anywhere that does not look like cf-worker (needs wrangler.jsonc and src/app/main.py).
It overwrites src/app/main.py (git keeps the previous version: `git diff src/app/main.py`) and creates or
overwrites test_stage6_routes.py and test_stage6_deployed.py. Nothing else is touched, nothing is deleted.
Each file carries a SHA-256 which is checked after writing and printed, and each .py is compile-checked.
"""
import base64, hashlib, py_compile, sys, zlib
from pathlib import Path

FILES = {
 "src/app/main.py": {
  "sha256": "bb2db54bd5c885aa7ec2513f329289433942bcf1d1b719b8b6821bac370ad5a8",
  "data": ""
 },
 "test_stage6_routes.py": {
  "sha256": "1cfed94315c0ac80dd71468bf382b4aea53c8e90f7ffa09a87771afaad59d657",
  "data": ""
 },
 "test_stage6_deployed.py": {
  "sha256": "6cbc46c7df1784ad48cd74166ba58f6eafc81e064a47c3bb15355dca4cfaf68c",
  "data": ""
 }
}

root = Path.cwd()
if not (root / "wrangler.jsonc").exists() or not (root / "src" / "app" / "main.py").exists():
    sys.exit("This does not look like the cf-worker folder (wrangler.jsonc and src/app/main.py not found here).\n"
             "Run:  cd /workspaces/boltane-workers-poc/files12/cf-worker   and try again.")

failed = False
for target, info in FILES.items():
    raw = zlib.decompress(base64.b64decode(info["data"]))
    if hashlib.sha256(raw).hexdigest() != info["sha256"]:
        print(f"FAIL  {target}: embedded data is corrupted (hash mismatch) - download install_stage6.py again")
        failed = True
        continue
    path = root / target
    existed = path.exists()
    path.write_bytes(raw)
    try:
        py_compile.compile(str(path), doraise=True, cfile="/tmp/_stage6_check.pyc")
        status = "compiles"
    except py_compile.PyCompileError as exc:
        status, failed = f"DOES NOT COMPILE: {exc}", True
    print(f"{'REPLACED' if existed else 'CREATED '}  {target}   sha256={info['sha256'][:12]}...  {status}")

print()
print("FAILED - see above" if failed else "Done. Next:  PYTHONPATH=tooling/local-test-support:src python test_stage6_routes.py")
sys.exit(1 if failed else 0)
